import java.nio.file.*;import java.util.*;import org.jf.dexlib2.*;import org.jf.dexlib2.iface.*;import org.jf.dexlib2.rewriter.*;import org.jf.dexlib2.writer.pool.DexPool;
public class RestoreDexNames{public static void main(String[] a)throws Exception{Map<String,String> map=new HashMap<>();for(String s:Files.readAllLines(Paths.get(a[0]))){String[] p=s.split("\t");map.put("L"+p[0].replace('.','/')+";","L"+p[1].replace('.','/')+";");}DexRewriter rw=new DexRewriter(new RewriterModule(){public Rewriter<String> getTypeRewriter(Rewriters r){return new TypeRewriter(){public String rewrite(String v){String b=v;int n=0;while(b.startsWith("[")){n++;b=b.substring(1);}String x=map.get(b);return x==null?v:"[".repeat(n)+x;}};}});var container=DexFileFactory.loadDexContainer(new java.io.File(a[1]),Opcodes.forApi(28));Files.createDirectories(Paths.get(a[2]));for(String name:container.getDexEntryNames()){System.out.println("Restoring type references: "+name);DexFile f=container.getEntry(name).getDexFile();DexPool.writeTo(a[2]+"/"+name,rw.getDexFileRewriter().rewrite(f));System.gc();}}}
